css:
/* TUI Copilot CLI - TUI Layout (Dark & Light) */
:root,.dark{--radius:4px!important}
.dark{--tui-text:#e6edf3;--tui-heading:#ffffff;--tui-inline-code:#56d4dd;--tui-user-bg:#21262d;--tui-user-fg:#f0f6fc;--tui-user-prompt:#8b949e;--tui-dot:#e6edf3;--tui-code-bg:#010409;--tui-code-border:#30363d;--tui-composer-bg:#0d1117;--tui-composer-border:#30363d;--tui-accent:#a371f7;--tui-border:#30363d;--tui-overlay-bg:rgba(13, 17, 23, 0.94);--tui-overlay-border:rgba(163, 113, 247, 0.22);--tui-overlay-shadow:0 12px 36px -8px rgba(0,0,0,.75);--tui-tooltip-bg:#21262d;--tui-tooltip-border:#30363d;--tui-scroll-thumb:#30363d;--tui-work-ok:#3fb950;--tui-work-err:#f85149;--tui-header-border:#21262d;--tui-crt-svg:url("data:image/svg+xml;base64,")}
:root:not(.dark){--tui-text:#1f2328;--tui-heading:#0d1117;--tui-inline-code:#1b7c83;--tui-user-bg:#eaeef2;--tui-user-fg:#1f2328;--tui-user-prompt:#656d76;--tui-dot:#1f2328;--tui-code-bg:#f6f8fa;--tui-code-border:#d0d7de;--tui-composer-bg:#ffffff;--tui-composer-border:#c8d1da;--tui-accent:#8250df;--tui-border:#d0d7de;--tui-overlay-bg:rgba(255, 255, 255, 0.95);--tui-overlay-border:rgba(130, 80, 223, 0.2);--tui-overlay-shadow:0 12px 32px -8px rgba(0,0,0,.16);--tui-tooltip-bg:#eaeef2;--tui-tooltip-border:#c8d1da;--tui-scroll-thumb:#c2c9d1;--tui-work-ok:#1a7f37;--tui-work-err:#cf222e;--tui-header-border:#d8dee4;--tui-crt-svg:url("data:image/svg+xml;base64,")}
body{letter-spacing:-.01em;-webkit-font-smoothing:antialiased;font-feature-settings:"ss01","calt"}
.messages-timeline-scroll,.chat-markdown,[data-user-message-bubble]{font-family:"CommitMono Nerd Font Mono","CommitMono Nerd Font","CommitMonoNerdFontMono","CommitMono",var(--font-mono)!important}
.chat-markdown,[data-user-message-bubble]{font-size:.9375rem!important}
.chat-markdown{line-height:1.44!important;color:var(--tui-text)!important}
.chat-markdown strong,.chat-markdown b,.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{color:var(--tui-heading)!important;font-weight:550!important}
.chat-markdown :not(pre)>code{background:transparent!important;border:0!important;padding:0!important;border-radius:0!important;color:var(--tui-inline-code)!important;font-weight:500!important}
[data-message-role="user"],[data-message-role="user"]>div{justify-content:flex-start!important;align-items:flex-start!important;width:100%!important}
[data-message-role="user"]{padding-top:10px!important;padding-bottom:4px!important}
[data-user-message-bubble]{position:relative!important;width:100%!important;max-width:100%!important;margin:0!important;background:var(--tui-user-bg)!important;border:0!important;border-radius:2px!important;box-shadow:none!important;padding:5px 10px 5px 1.8em!important;color:var(--tui-user-fg)!important}
[data-user-message-bubble]::before{content:">";position:absolute;left:.65em;top:5px;color:var(--tui-user-prompt);font-weight:700}
[data-message-role="assistant"]{position:relative!important;border-left:0!important;padding-left:16px!important}
[data-message-role="assistant"]::before{content:"";position:absolute;left:2px;top:.55em;width:7px;height:7px;border-radius:50%;background:var(--tui-dot)}
.chat-markdown-codeblock{border:1px solid var(--tui-code-border)!important;border-radius:3px!important;background:var(--tui-code-bg)!important;box-shadow:none!important}
[data-slot="composer-host"]{background:var(--tui-composer-bg)!important;border:0!important;border-top:1px solid var(--tui-composer-border)!important;border-bottom:1px solid var(--tui-composer-border)!important;border-radius:0!important;box-shadow:none!important;transition:border-color .15s ease}
[data-slot="composer-host"]:focus-within{border-top-color:var(--tui-accent)!important;border-bottom-color:var(--tui-accent)!important;box-shadow:none!important}
*:has(>*>.composer-tiptap):not([data-slot="composer-host"]):not([data-chat-composer-form]){position:relative!important;margin-left:1.45em!important;overflow:visible!important}
*:has(>*>.composer-tiptap):not([data-slot="composer-host"]):not([data-chat-composer-form])::before{content:">";position:absolute;left:-1.25em;top:.08em;color:var(--tui-user-prompt);font-family:"CommitMono Nerd Font Mono","CommitMono Nerd Font",var(--font-mono);font-weight:700;pointer-events:none;transition:color .15s ease}
[data-slot="composer-host"]:focus-within *:has(>*>.composer-tiptap):not([data-slot="composer-host"]):not([data-chat-composer-form])::before{color:var(--tui-accent)}
[data-slot="sidebar"],[data-chat-header]{border-color:var(--tui-border)!important}
[data-thread-item]{border-radius:4px!important}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:6px!important;border:1px solid var(--tui-overlay-border)!important;background:var(--tui-overlay-bg)!important;backdrop-filter:blur(12px);box-shadow:var(--tui-overlay-shadow)!important}
[data-slot="tooltip-popup"]{border-radius:4px!important;background:var(--tui-tooltip-bg)!important;border:1px solid var(--tui-tooltip-border)!important}
svg.lucide{stroke-width:1.5!important;stroke-linecap:round!important;stroke-linejoin:round!important}
::-webkit-scrollbar{width:7px!important;height:7px!important}
::-webkit-scrollbar-thumb,[data-slot="scroll-area-thumb"]{background:transparent!important;border-radius:4px!important}
:hover::-webkit-scrollbar-thumb,[data-slot="scroll-area-scrollbar"]:hover [data-slot="scroll-area-thumb"]{background-color:var(--tui-scroll-thumb)!important}
.messages-timeline-scroll{padding-left:10%!important;padding-right:10%!important}
.messages-timeline-scroll>div{max-width:100%!important;padding-left:0!important;padding-right:0!important}
.messages-timeline-scroll div:has([data-timeline-row-kind]),.messages-timeline-scroll [data-timeline-row-kind],.messages-timeline-scroll [data-timeline-row-kind]>div,.messages-timeline-scroll [data-message-role="assistant"],.messages-timeline-scroll [data-message-role="assistant"]>div,.messages-timeline-scroll .chat-markdown,.messages-timeline-scroll [data-thread-details-card]{max-width:100%!important}
*:has([data-slot="composer-host"]):not(html):not(body):not(:has(.messages-timeline-scroll)):not(:has([data-slot="sidebar"])):not(:has([data-chat-header])):not([data-slot="composer-host"]):not([data-chat-composer-form]){max-width:100%!important;width:100%!important;padding-left:0!important;padding-right:0!important;background:transparent!important;background-color:transparent!important;border:0!important;box-shadow:none!important}
*:has(>[data-slot="composer-host"])::before,*:has(>[data-slot="composer-host"])::after,*:has(>[data-chat-composer-form])::before,*:has(>[data-chat-composer-form])::after,[data-chat-composer-form]{background:transparent!important;background-color:transparent!important;border:0!important;box-shadow:none!important}
[data-chat-composer-form]:has([data-slot="composer-host"]){width:80%!important;max-width:80%!important;margin-left:auto!important;margin-right:auto!important;padding-left:0!important;padding-right:0!important}
[data-chat-composer-form] :has([data-slot="composer-host"]),[data-chat-composer-form] [data-slot="composer-host"],[data-slot="composer-host"] [data-chat-composer-form]{width:100%!important;max-width:100%!important}
[data-slot="composer-host"]:not([data-chat-composer-form] [data-slot="composer-host"]),[data-chat-composer-form]:has([data-slot="composer-host"])~div:not(.messages-timeline-scroll):not([data-thread-terminal-drawer]),[data-slot="composer-host"]:not([data-chat-composer-form] [data-slot="composer-host"])~div:not(.messages-timeline-scroll):not([data-thread-terminal-drawer]){width:80%!important;max-width:80%!important;margin-left:auto!important;margin-right:auto!important}
@keyframes claude-work-dot-blink{0%,100%{opacity:1}50%{opacity:.2}}
[data-timeline-row-kind="work"]{position:relative!important;padding-left:16px!important}
[data-timeline-row-kind="work"]::before{content:"";position:absolute;left:2px;top:.65em;width:7px;height:7px;border-radius:50%;background:var(--tui-work-ok);transition:background-color .2s ease}
[data-timeline-row-kind="work"]:has(svg.lucide-circle-x,svg.lucide-x,svg.lucide-circle-alert,svg.lucide-triangle-alert,svg.lucide-alert-circle,svg.lucide-alert-triangle,[class*="text-destructive"],[class*="text-error"],[class*="text-red"],[data-status="error"],[data-status="failed"])::before{background:var(--tui-work-err);animation:none}
[data-timeline-row-kind="work"]:has(.animate-spin,.animate-pulse,svg.lucide-loader-circle,svg.lucide-loader-2,svg.lucide-loader,[aria-busy="true"],[data-status="running"])::before{background:var(--tui-dot);animation:claude-work-dot-blink 1.1s ease-in-out infinite}
[data-workspace-area="conversation"]:not(:has([data-timeline-row-kind]))::before{content:""!important;display:block!important;width:80%!important;height:158px!important;margin:14px auto 12px!important;padding-bottom:12px!important;border-bottom:1px dashed var(--tui-header-border)!important;background-image:var(--tui-crt-svg)!important;background-repeat:no-repeat!important;background-position:left top!important;background-size:520px 146px!important;flex-shrink:0!important;pointer-events:none!important}
@media (max-resolution:1.25dppx){body{letter-spacing:0!important;-webkit-font-smoothing:auto!important}.chat-markdown,[data-user-message-bubble]{font-size:15px!important;line-height:1.46!important}}
@media (prefers-reduced-motion:reduce){[data-timeline-row-kind="work"]::before{animation:none!important}[data-slot="composer-host"],*:has(>*>.composer-tiptap)::before{transition:none!important}}
